#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_force;
uniform float amzp_gravity;
uniform float amzp_spinRate;
uniform float2 amzp_forceCenter;
uniform float amzp_dirRand;
uniform float amzp_speedRand;
uniform float amzp_grid;
uniform float amzp_objectType;
uniform float amzp_startTime;
uniform float amzp_depthAmount;
uniform float amzp_searchMax;
uniform float amzp_seed;





    float hash12(float2 p){
      float3 p3 = fract(float3(p.xyx) * 0.1031);
      p3 += dot(p3, p3.yzx + 33.33);
      return fract((p3.x + p3.y) * p3.z);
    }

    float2x2 r2(float a){ float s = sin(a), c = cos(a); return float2x2(c,-s,s,c); }


    bool triMask(float2 q, bool diag){

      float e = 1e-5;
      if(!diag){
        return (q.x + q.y) <= 1.0 - e;
      } else {
        return (q.x - q.y) >= e;
      }
    }

    float2 toPx(float2 uv){ return uv * getTexSize((screen.zw/1.0)); }
    float2 toUv(float2 px){ float2 s = getTexSize((screen.zw/1.0)); return px / max(s, float2(1.0)); }

    float4 sampleSafe(float2 uv){
      return amzTexture(0, clamp(uv, 0.0, 1.0));
    }

    struct PieceParams { float2 disp; float rot; float2 pivotUv; bool diag; float scale; float depth; };

    PieceParams getPiece(float2 cid, float t, float g){
      PieceParams P;
      float2 texSize = getTexSize((screen.zw/1.0));
      float rnd1 = hash12(cid + float(amzp_seed));
      float rnd2 = hash12(cid.yx + float(amzp_seed)*1.113);
      bool diag = mod(cid.x + cid.y, 2.0) < 0.5; P.diag = diag;


      float2 cellOriginPx = (cid + 0.5) * g;
      float2 triPivotOff = (diag ? float2(0.25, 0.75) : float2(0.75, 0.25)) - float2(0.5);
      float2 pivotPx = cellOriginPx + triPivotOff * g * 0.5;
      P.pivotUv = toUv(pivotPx);


      float2 fc = amzp_forceCenter;
      float2 dir = normalize((toUv(cellOriginPx) - fc));
      float angleJitter = (rnd1 - 0.5) * 6.28318530718 * amzp_dirRand;
      dir = r2(angleJitter) * dir;
      float speedMul = 1.0 + (rnd2 - 0.5) * 2.0 * amzp_speedRand;

      float F = amzp_force / max(texSize.x, texSize.y);
      float2 v0 = dir * F * speedMul;
      float2 gy = float2(0.0, -amzp_gravity / max(texSize.y, 1.0));
      P.disp = v0 * t + 0.5 * gy * (t*t);
      P.rot = radians(amzp_spinRate) * t * (0.5 + rnd1);

      P.depth = amzp_depthAmount * t * (0.25 + rnd2); 
      P.scale = 1.0 / (1.0 + max(P.depth, 0.0));
      return P;
    }


    float4 tryCandidate(float2 cidC, float t, float g, float2 uvNow, out bool ok){
      PieceParams P = getPiece(cidC, t, g);

      float2 uv0 = uvNow - P.disp;

      uv0 = (r2(-P.rot) * ((uv0 - P.pivotUv) / max(P.scale, 1e-4))) + P.pivotUv;

      float2 pxy0 = toPx(uv0);
      float2 cid0 = floor(pxy0 / g);
      float2 q0 = fract(pxy0 / g);
      bool diag0 = mod(cid0.x + cid0.y, 2.0) < 0.5;
      bool inside0 = triMask(q0, diag0);

      bool sameCell = all(lessThan(abs(cid0 - cidC), float2(0.25)));
      ok = sameCell && inside0;
      float4 s = ok ? sampleSafe(uv0) : float4(0.0);

      s.a = ok ? P.depth : 1e9;
      return s;
    }

    void amzRender(){

      if (time < amzp_startTime) {
        float4 src0 = amzTexture(0, amzScreenNorm());
        amzOutput = src0;
        return;
      }
      float t = max(0.0, time - amzp_startTime);
      float g = max(amzp_grid, 2.0);
      float2 uvNow = amzScreenNorm();


      float2 pxy = toPx(uvNow);
      float2 baseCid = floor(pxy / g);


      float texMax = max(getTexSize((screen.zw/1.0)).x, getTexSize((screen.zw/1.0)).y);
      float estDisp = (amzp_force / max(texMax, 1.0)) * t + 0.5 * abs(amzp_gravity / max(texMax, 1.0)) * t*t; 
      float cells = estDisp * (texMax / g); 
      int Rcap = int(clamp(amzp_searchMax, 1.0, 12.0));
      int R = int(clamp(ceil(cells) + 1.0, 1.0, float(Rcap))); 

      float4 col = float4(0.0);
      bool found = false;
      float bestDepth = 1e9;
      for(int dy=-4; dy<=4 && !found; ++dy){
        if(dy < -R || dy > R) continue;
        for(int dx=-4; dx<=4 && !found; ++dx){
          if(dx < -R || dx > R) continue;
          float2 cidC = baseCid + float2(float(dx), float(dy));
          bool ok; float4 c = tryCandidate(cidC, t, g, uvNow, ok);
          if(ok){

            if(c.a < bestDepth){ bestDepth = c.a; col = float4(c.rgb, 1.0); }
            found = true;
          }
        }
      }

      amzOutput = found ? col : float4(0.0);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

